begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temp table user_management_fixture(kind text,id uuid,auth_id uuid,tenant_id uuid,branch_id uuid,department_id uuid);
do $$ declare tenant uuid; branch uuid; department uuid; person uuid; aid uuid; kind text; begin
 foreach kind in array array['manager','buddy_one','buddy_two','denied','other_tenant'] loop
  if kind in ('manager','other_tenant') then
   insert into tenants(name,slug) values('User permission '||kind,'user-permission-'||kind) returning id into tenant;
   insert into branches(tenant_id,name,code) values(tenant,'Permission branch','UPR') returning id into branch;
   insert into departments(tenant_id,branch_id,name,code) values(tenant,branch,'Permission department','UPR') returning id into department;
  else select tenant_id,branch_id,department_id into tenant,branch,department from user_management_fixture where user_management_fixture.kind='manager'; end if;
  aid:=gen_random_uuid();
  insert into auth.users(id,aud,role,email,encrypted_password,created_at,updated_at) values(aid,'authenticated','authenticated','permission-'||kind||'@example.in','x',now(),now());
  insert into user_profiles(tenant_id,auth_user_id,branch_id,department_id,employee_name,employee_code,email,user_role,working_status,account_status,is_login_enabled)
  values(tenant,aid,branch,department,'Permission '||kind,'UPR-'||kind,'permission-'||kind||'@example.in',case when kind='manager' then 'hr'::user_role else 'staff'::user_role end,'active','active',true) returning id into person;
  insert into user_management_fixture values(kind,person,aid,tenant,branch,department);
 end loop;
end $$;
-- Reproduce an HR employee assigned Staff dashboard authority, then granted management.
insert into user_access_profiles(user_profile_id,tenant_id,dashboard_authority) select id,tenant_id,'staff' from user_management_fixture where kind='manager';
insert into user_permission_overrides(user_profile_id,tenant_id,permission_key,effect) select id,tenant_id,'users.manage','grant' from user_management_fixture where kind='manager';
grant select on user_management_fixture to authenticated,service_role;
create function pg_temp.fixture(p_kind text) returns user_management_fixture language sql as $$ select * from user_management_fixture where kind=p_kind $$;
grant execute on function pg_temp.fixture(text) to authenticated,service_role;
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub',(pg_temp.fixture('manager')).auth_id::text,true);
select ok(has_permission('users.manage'),'configured management permission is effective');
select is((select count(*)::int from user_profiles where id in ((pg_temp.fixture('buddy_one')).id,(pg_temp.fixture('buddy_two')).id)),2,'granted HR can load both buddy choices even with Staff dashboard authority');
select is((select count(*)::int from user_profiles where tenant_id=(pg_temp.fixture('other_tenant')).tenant_id),0,'management grant never exposes another tenant');
select throws_ok($$select create_user_profile_with_coverage_and_audit(gen_random_uuid(),(pg_temp.fixture('manager')).id,'new@example.in','New','Employee','official@example.in',(pg_temp.fixture('manager')).branch_id,(pg_temp.fixture('manager')).department_id,null,'',null,'{}','staff',null,null,null)$$,'42501',null,'browser cannot impersonate a service-side inviter');
reset role;
create temp table invited_fixture(id uuid,auth_id uuid);
insert into invited_fixture values(null,gen_random_uuid());
insert into auth.users(id,aud,role,email,encrypted_password,created_at,updated_at) select auth_id,'authenticated','authenticated','new@example.in','x',now(),now() from invited_fixture;
grant select,update on invited_fixture to service_role;
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select lives_ok($$update invited_fixture set id=create_user_profile_with_coverage_and_audit(auth_id,(pg_temp.fixture('manager')).id,'new@example.in','New','Employee','official@example.in',(pg_temp.fixture('manager')).branch_id,(pg_temp.fixture('manager')).department_id,null,'',null,'{}','staff',(pg_temp.fixture('buddy_one')).id,(pg_temp.fixture('buddy_two')).id,(pg_temp.fixture('buddy_one')).id)$$,'granted HR creates an employee with .in emails and both buddies');
reset role;
select ok(exists(select 1 from user_profiles p join invited_fixture i on p.id=i.id where p.buddy_id=(pg_temp.fixture('buddy_one')).id and p.secondary_buddy_id=(pg_temp.fixture('buddy_two')).id and p.reports_to_user_id=(pg_temp.fixture('buddy_one')).id and p.email='new@example.in' and p.official_email='official@example.in'),'complete account data is persisted');
select ok(exists(select 1 from audit_logs a join invited_fixture i on a.record_id=i.id where a.actor_user_id=(pg_temp.fixture('manager')).id and a.action='user_created'),'account creation records the real inviter in the audit');
select ok(exists(select 1 from audit_logs a join invited_fixture i on a.record_id=i.id where a.actor_user_id=(pg_temp.fixture('manager')).id and a.action='user_coverage_profile_configured'),'coverage is audited in the same contract');
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub',(pg_temp.fixture('manager')).auth_id::text,true);
select lives_ok($$select update_user_profile_with_audit((pg_temp.fixture('buddy_two')).id,'{"employee_name":"Edited by permitted HR"}')$$,'granted HR can use the existing audited account editor');
select throws_ok($$select update_user_profile_with_audit((pg_temp.fixture('other_tenant')).id,'{"employee_name":"Forbidden"}')$$,'42501',null,'editing cannot cross tenant boundaries');
reset role;
insert into user_access_profiles(user_profile_id,tenant_id,dashboard_authority) select id,tenant_id,'super_admin' from user_management_fixture where kind='denied';
insert into user_permission_overrides(user_profile_id,tenant_id,permission_key,effect) select id,tenant_id,'users.delete','grant' from user_management_fixture where kind='manager';
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub',(pg_temp.fixture('manager')).auth_id::text,true);
select throws_ok($$select update_user_profile_with_audit((pg_temp.fixture('denied')).id,'{"employee_name":"Forbidden protected edit"}')$$,'42501',null,'management cannot edit an employee with Super Admin dashboard authority');
select throws_ok($$select prepare_unused_user_deletion((pg_temp.fixture('denied')).id)$$,'42501',null,'delete permission cannot target Super Admin dashboard authority');
reset role;
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select throws_ok($$select configure_invited_profile_coverage_with_audit((pg_temp.fixture('manager')).id,(pg_temp.fixture('denied')).id,null,null)$$,'42501',null,'service coverage cannot change a protected authority account');
select throws_ok($$select invite_profile_with_audit_v3(gen_random_uuid(),(pg_temp.fixture('manager')).id,'admin@example.in','Protected','','',(pg_temp.fixture('manager')).branch_id,(pg_temp.fixture('manager')).department_id,null,'',null,'{}','super_admin',null)$$,'42501',null,'user management never grants Super Admin account creation');
select throws_ok($$select configure_invited_profile_coverage_with_audit((pg_temp.fixture('manager')).id,(pg_temp.fixture('other_tenant')).id,null,null)$$,'42501',null,'service coverage cannot cross tenant boundaries');
reset role;
delete from user_permission_overrides where user_profile_id=(pg_temp.fixture('manager')).id and permission_key='users.delete';
update user_profiles set account_status='suspended' where id=(pg_temp.fixture('manager')).id;
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select throws_ok($$select invite_profile_with_audit_v3(gen_random_uuid(),(pg_temp.fixture('manager')).id,'inactive@example.in','Inactive','','',(pg_temp.fixture('manager')).branch_id,(pg_temp.fixture('manager')).department_id,null,'',null,'{}','staff',null)$$,'42501',null,'suspended inviter is denied despite an existing grant');
select throws_ok($$select configure_invited_profile_coverage_with_audit((pg_temp.fixture('manager')).id,(select id from invited_fixture),null,null)$$,'42501',null,'suspended inviter cannot configure coverage');
reset role;
update user_profiles set account_status='active',is_login_enabled=true where id=(pg_temp.fixture('manager')).id;
update user_permission_overrides set effect='deny' where user_profile_id=(pg_temp.fixture('manager')).id and permission_key='users.manage';
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub',(pg_temp.fixture('manager')).auth_id::text,true);
select is((select count(*)::int from user_profiles where id in ((pg_temp.fixture('buddy_one')).id,(pg_temp.fixture('buddy_two')).id)),0,'revoked grant restores original Staff data scope');
reset role;
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select throws_ok($$select configure_invited_profile_coverage_with_audit((pg_temp.fixture('manager')).id,(select id from invited_fixture),null,null)$$,'42501',null,'revoked management cannot configure coverage through the API');
select throws_ok($$select invite_profile_with_audit_v3(gen_random_uuid(),(pg_temp.fixture('manager')).id,'revoked@example.in','Revoked','','',(pg_temp.fixture('manager')).branch_id,(pg_temp.fixture('manager')).department_id,null,'',null,'{}','staff',null)$$,'42501',null,'revoked management cannot create accounts through the API');
reset role;
insert into user_permission_overrides(user_profile_id,tenant_id,permission_key,effect) select id,tenant_id,'users.delete','grant' from user_management_fixture where kind='manager';
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub',(pg_temp.fixture('manager')).auth_id::text,true);
select is((select count(*)::int from user_profiles where id in ((pg_temp.fixture('buddy_one')).id,(pg_temp.fixture('buddy_two')).id)),2,'delete-only permission can read eligible account targets');
select is((select count(*)::int from user_profiles where tenant_id=(pg_temp.fixture('other_tenant')).tenant_id),0,'delete-only read scope never crosses tenants');
select throws_ok($$select update_user_profile_with_audit((pg_temp.fixture('buddy_two')).id,'{"employee_name":"Forbidden edit"}')$$,'42501',null,'delete permission never grants editing');
reset role;
select * from finish();
rollback;
